new_css=".shell{width:100%;max-width:820px;min-height:100dvh;margin:auto;padding:env(safe-area-inset-top) 16px calc(28px + env(safe-area-inset-bottom));position:relative;z-index:2;background:var(--bg)}.top{display:flex;justify-content:space-between;align-items:center;padding:16px 0 10px;background:var(--bg)}.eyebrow,.kicker{font-size:12px;color:var(--muted);text-transform:uppercase;letter-spacing:.08em;font-weight:700}.top h1{margin:3px 0 0;font-size:24px}.quickbar{position:sticky;top:calc(env(safe-area-inset-top) + 6px);z-index:24;display:grid;grid-template-columns:minmax(0,1fr) auto auto;gap:7px;align-items:stretch;margin:0 -4px 14px;padding:7px;border:1px solid var(--line);border-radius:17px;background:var(--bg);background:color-mix(in srgb,var(--bg) 88%,transparent);box-shadow:0 8px 24px rgba(0,0,0,.18);backdrop-filter:blur(18px);-webkit-backdrop-filter:blur(18px)}.quick-status{display:flex;min-width:0;flex-direction:column;justify-content:center;padding:3px 7px}.quick-status span{font-size:9px;color:var(--muted);text-transform:uppercase;letter-spacing:.07em;font-weight:800}.quick-status strong{margin-top:1px;font-size:16px;line-height:1.1;white-space:nowrap}.quick-status small{display:block;margin-top:3px;font-size:10px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.quick-primary,.quick-settings{border:1px solid var(--line);border-radius:12px;min-height:50px;padding:7px 10px;color:var(--text);font:inherit;font-weight:750;cursor:pointer}.quick-primary{min-width:112px;background:var(--accent);color:#fff;border-color:transparent}.quick-primary strong,.quick-primary small,.quick-settings span{display:block}.quick-primary strong{font-size:12px}.quick-primary small{margin-top:1px;color:rgba(255,255,255,.78);font-size:9px}.quick-settings{min-width:82px;background:var(--card2);display:flex;flex-direction:column;align-items:center;justify-content:center}.quick-settings-icon{font-size:18px;line-height:1}.quick-settings-label{margin-top:2px;font-size:9px}.quickbar button:active{transform:scale(.97)}.editor-view .quickbar{display:none}.screen-swipe-backdrop{position:fixed;inset:0;z-index:1;visibility:hidden;opacity:0;overflow:hidden;padding:calc(env(safe-area-inset-top) + 28px) 18px calc(26px + env(safe-area-inset-bottom));background:var(--bg);pointer-events:none;transition:opacity .12s ease}.screen-swipe-backdrop.show{visibility:visible;opacity:1}.screen-swipe-preview-inner{max-width:820px;margin:auto;transform:translateX(32px);opacity:.72;transition:transform .12s linear,opacity .12s linear}.screen-swipe-backdrop.from-left .screen-swipe-preview-inner{transform:translateX(-32px)}.screen-swipe-backdrop.engaged .screen-swipe-preview-inner{transform:translateX(0);opacity:1}.screen-preview-title{margin:4px 0 18px;font-size:28px}.screen-preview-card{padding:15px;border:1px solid var(--line);border-radius:16px;background:var(--card);margin-bottom:10px}.screen-preview-card strong,.screen-preview-card small{display:block}.screen-preview-card small{margin-top:4px}.shell.screen-swiping{will-change:transform;pointer-events:none}.screen-swipe-edge-cue{position:fixed;right:0;top:46%;z-index:8;width:10px;height:48px;border-radius:10px 0 0 10px;background:color-mix(in srgb,var(--accent) 44%,transparent);opacity:.45;pointer-events:none}.editor-view .screen-swipe-edge-cue,.has-active-trip .screen-swipe-edge-cue{opacity:.28}@media(max-width:430px){.quickbar{grid-template-columns:minmax(0,1fr) 104px 70px;gap:5px}.quick-status{padding-left:5px}.quick-primary{min-width:0;padding-left:6px;padding-right:6px}.quick-settings{min-width:0;padding-left:5px;padding-right:5px}.quick-settings-label{font-size:8px}}@media(prefers-reduced-motion:reduce){.screen-swipe-backdrop,.screen-swipe-preview-inner,.shell{transition:none!important}}"
if old_css not in s: raise SystemExit('top css marker not found')
s=s.replace(old_css,new_css,1)

old_body='''<body>\n<div class="shell">\n<header class="top">\n<div><div id="today" class="eyebrow"></div><h1>Kilometerregistratie</h1></div>\n<button id="topAction" class="iconbtn" data-action="settings" aria-label="Instellingen">⚙︎</button>\n</header>\n<main id="app"></main>\n</div>'''
new_body='''<body>\n<div id="screenSwipeBackdrop" class="screen-swipe-backdrop" aria-hidden="true"></div>\n<div id="screenSwipeEdgeCue" class="screen-swipe-edge-cue" aria-hidden="true"></div>\n<div class="shell" id="screenShell">\n<header class="top">\n<div><div id="today" class="eyebrow"></div><h1>Kilometerregistratie</h1></div>\n</header>\n<div id="quickBar" class="quickbar" aria-label="Snelle acties">\n<div id="quickStatus" class="quick-status"></div>\n<button id="quickPrimary" class="quick-primary" type="button" data-action="quick-primary"></button>\n<button id="topAction" class="quick-settings" type="button" data-action="settings" aria-label="Instellingen"><span class="quick-settings-icon">⚙︎</span><span class="quick-settings-label">Instellingen</span></button>\n</div>\n<main id="app"></main>\n</div>'''
