old_refs="const app=document.getElementById('app'),modal=document.getElementById('modal'),modalPanel=document.getElementById('modalPanel'),toastEl=document.getElementById('toast'),topAction=document.getElementById('topAction'),printReportEl=document.getElementById('printReport');"
new_refs="const app=document.getElementById('app'),modal=document.getElementById('modal'),modalPanel=document.getElementById('modalPanel'),toastEl=document.getElementById('toast'),topAction=document.getElementById('topAction'),quickStatus=document.getElementById('quickStatus'),quickPrimary=document.getElementById('quickPrimary'),screenShell=document.getElementById('screenShell'),screenSwipeBackdrop=document.getElementById('screenSwipeBackdrop'),printReportEl=document.getElementById('printReport');"
