new_version="document.getElementById('today').textContent=new Intl.DateTimeFormat('nl-NL',{weekday:'long',day:'numeric',month:'long'}).format(new Date())+' · 0.28.20';"
if old_version not in s: raise SystemExit('version marker not found')
s=s.replace(old_version,new_version,1)

old_render="function render(){const editor=view==='trip-edit'||view==='location-edit';document.body.classList.toggle('editor-view',editor);document.body.classList.toggle('has-active-trip',view==='ride'&&!!data.activeTrip);if(view==='trip-edit'){renderTripEditPage();return}if(view==='location-edit'){renderLocationEditPage();return}if(view==='settings'){topAction.dataset.action='home';topAction.textContent='←';topAction.setAttribute('aria-label','Terug');renderSettings()}else{view='ride';topAction.dataset.action='settings';topAction.textContent='⚙︎';topAction.setAttribute('aria-label','Instellingen');renderHome()}}"
new_render="""function quickBarLocation(){const active=data.activeTrip,last=data.lastEndpoint||inferLast();return active?.origin||last?.location||null}\nfunction quickBarStand(){const active=data.activeTrip,last=data.lastEndpoint||inferLast(),fallback=num(data.settings.initialOdometer);return active?.startOdometer??last?.odometer??fallback}\nfunction renderQuickBar(){const active=data.activeTrip,stand=quickBarStand(),loc=quickBarLocation(),inSettings=view==='settings';quickStatus.innerHTML=`<span>${active?'Startstand':'Kilometerstand'}</span><strong>${stand!=null?odo(stand)+' km':'—'}</strong><small>${loc?esc(labelLoc(loc)):'Nog geen locatie'}</small>`;quickPrimary.dataset.action='quick-primary';quickPrimary.innerHTML=active?'<strong>Aankomst</strong><small>rit afronden</small>':'<strong>Vertrek</strong><small>registreren</small>';quickPrimary.setAttribute('aria-label',active?'Rit afronden':'Vertrek registreren');topAction.dataset.action=inSettings?'home':'settings';topAction.innerHTML=inSettings?'<span class=\"quick-settings-icon\">←</span><span class=\"quick-settings-label\">Ritten</span>':'<span class=\"quick-settings-icon\">⚙︎</span><span class=\"quick-settings-label\">Instellingen</span>';topAction.setAttribute('aria-label',inSettings?'Terug naar ritten':'Instellingen')}\nasync function runQuickPrimary(){if(view!=='ride'){view='ride';window.scrollTo({top:0,behavior:'instant'});render()}if(data.activeTrip){if(arrivalDraft){document.getElementById('arrivalInlinePanel')?.scrollIntoView({behavior:'smooth',block:'start'});return}await openArrival();return}if(startDraft){document.getElementById('startInlinePanel')?.scrollIntoView({behavior:'smooth',block:'start'});return}await openStart()}\nfunction render(){const editor=view==='trip-edit'||view==='location-edit';document.body.classList.toggle('editor-view',editor);document.body.classList.toggle('has-active-trip',view==='ride'&&!!data.activeTrip);if(view==='trip-edit'){renderTripEditPage();return}if(view==='location-edit'){renderLocationEditPage();return}renderQuickBar();if(view==='settings')renderSettings();else{view='ride';renderHome()}}"""
if old_render not in s: raise SystemExit('render marker not found')
s=s.replace(old_render,new_render,1)

old_click="if(a==='settings'){view='settings';render()}else if(a==='home'){view='ride';render()}else if(a==='editor-back')leaveEditor();"
new_click="if(a==='settings'){view='settings';window.scrollTo({top:0,behavior:'instant'});render()}else if(a==='home'){view='ride';window.scrollTo({top:0,behavior:'instant'});render()}else if(a==='quick-primary')await runQuickPrimary();else if(a==='editor-back')leaveEditor();"
if old_click not in s: raise SystemExit('click navigation marker not found')
s=s.replace(old_click,new_click,1)

old_swipe="""function screenSwipeStart(e){
if(e.button!=null&&e.button!==0)return;if(!modal.hidden)return;
const width=Math.max(document.documentElement.clientWidth||0,window.innerWidth||0),x=e.clientX;
const direction=view==='ride'&&x>=width-SCREEN_EDGE_SWIPE_ZONE?'left':(view==='settings'||view==='trip-edit'||view==='location-edit')&&x<=SCREEN_EDGE_SWIPE_ZONE?'right':null;
if(!direction)return;
const target=e.target instanceof Element?e.target:null;if(target?.closest('input,select,textarea,[contenteditable=\"true\"]'))return;
closeTripSwipes();screenSwipe={pointerId:e.pointerId,startX:x,startY:e.clientY,dx:0,dy:0,direction,horizontal:false,cancelled:false,target};
try{target?.setPointerCapture?.(e.pointerId)}catch(_){}
}
function screenSwipeMove(e){const g=screenSwipe;if(!g||g.pointerId!==e.pointerId||g.cancelled)return;const dx=e.clientX-g.startX,dy=e.clientY-g.startY;g.dx=dx;g.dy=dy;if(!g.horizontal){if(Math.abs(dy)>12&&Math.abs(dy)>Math.abs(dx)){g.cancelled=true;return}if(Math.abs(dx)>10&&Math.abs(dx)>Math.abs(dy)*1.15)g.horizontal=true;else return}const correct=g.direction==='left'?dx<0:dx>0;if(!correct){if(Math.abs(dx)>18)g.cancelled=true;return}if(e.cancelable)e.preventDefault()}
function screenSwipeEnd(e){const g=screenSwipe;if(!g||g.pointerId!==e.pointerId)return;screenSwipe=null;if(g.cancelled||!g.horizontal)return;const correct=g.direction==='left'?g.dx<=-SCREEN_EDGE_SWIPE_DISTANCE:g.dx>=SCREEN_EDGE_SWIPE_DISTANCE;if(!correct||Math.abs(g.dx)<Math.abs(g.dy)*1.2)return;if(g.direction==='left'&&view==='ride'){view='settings';render();return}if(g.direction==='right'&&view==='settings'){view='ride';render();return}if(g.direction==='right'&&(view==='trip-edit'||view==='location-edit'))leaveEditor()}
function screenSwipeCancel(){screenSwipe=null}
"""
new_swipe="""function screenSwipePreviewHtml(targetView){const stand=quickBarStand(),loc=quickBarLocation(),settings=targetView==='settings';return`<div class=\"screen-swipe-preview-inner\"><div class=\"kicker\">${settings?'Navigatie':'Kilometerregistratie'}</div><h2 class=\"screen-preview-title\">${settings?'Instellingen':'Ritten'}</h2>${settings?'<div class=\"screen-preview-card\"><strong>Auto & bestuurder</strong><small>Voertuig, beginstand en ritinstellingen</small></div><div class=\"screen-preview-card\"><strong>Locaties</strong><small>Opgeslagen locaties beheren</small></div><div class=\"screen-preview-card\"><strong>Data & back-up</strong><small>Back-up, import en rapportage</small></div>':`<div class=\"screen-preview-card\"><strong>${stand!=null?odo(stand)+' km':'Kilometerstand onbekend'}</strong><small>${loc?esc(labelLoc(loc)):'Nog geen laatste locatie'}</small></div><div class=\"screen-preview-card\"><strong>${data.activeTrip?'Actieve rit':'Vertrek registreren'}</strong><small>Terug naar het rittenoverzicht</small></div>`}</div>`}
function showScreenSwipeBackdrop(targetView,direction){screenSwipeBackdrop.innerHTML=screenSwipePreviewHtml(targetView);screenSwipeBackdrop.className='screen-swipe-backdrop show '+(direction==='right'?'from-left':'');requestAnimationFrame(()=>screenSwipeBackdrop.classList.add('engaged'))}
function hideScreenSwipeBackdrop(){screenSwipeBackdrop.className='screen-swipe-backdrop';screenSwipeBackdrop.innerHTML=''}
function resetScreenSwipeVisuals(){screenShell.classList.remove('screen-swiping');screenShell.style.transition='';screenShell.style.transform='';hideScreenSwipeBackdrop()}
function settleScreenSwipe(g,complete){const width=Math.max(document.documentElement.clientWidth||0,window.innerWidth||0),to=complete?(g.direction==='left'?-width:width):0;screenShell.style.transition='transform .2s cubic-bezier(.22,.8,.28,1)';screenShell.style.transform=`translate3d(${to}px,0,0)`;setTimeout(()=>{if(complete){if(g.direction==='left'&&view==='ride'){view='settings';render()}else if(g.direction==='right'&&view==='settings'){view='ride';render()}else if(g.direction==='right'&&(view==='trip-edit'||view==='location-edit')){resetScreenSwipeVisuals();leaveEditor();window.scrollTo({top:0,behavior:'instant'});return}window.scrollTo({top:0,behavior:'instant'})}resetScreenSwipeVisuals()},205)}
function screenSwipeStart(e){
if(e.button!=null&&e.button!==0)return;if(!modal.hidden)return;
const width=Math.max(document.documentElement.clientWidth||0,window.innerWidth||0),x=e.clientX;
const direction=view==='ride'&&x>=width-SCREEN_EDGE_SWIPE_ZONE?'left':(view==='settings'||view==='trip-edit'||view==='location-edit')&&x<=SCREEN_EDGE_SWIPE_ZONE?'right':null;
if(!direction)return;
const target=e.target instanceof Element?e.target:null;if(target?.closest('input,select,textarea,[contenteditable=\"true\"]'))return;
closeTripSwipes();screenSwipe={pointerId:e.pointerId,startX:x,startY:e.clientY,dx:0,dy:0,direction,horizontal:false,cancelled:false,target,startTime:performance.now(),lastX:x,lastMoveTime:performance.now(),velocityX:0,previewShown:false};
try{target?.setPointerCapture?.(e.pointerId)}catch(_){}
}
function screenSwipeMove(e){const g=screenSwipe;if(!g||g.pointerId!==e.pointerId||g.cancelled)return;const dx=e.clientX-g.startX,dy=e.clientY-g.startY;g.dx=dx;g.dy=dy;if(!g.horizontal){if(Math.abs(dy)>12&&Math.abs(dy)>Math.abs(dx)){g.cancelled=true;return}if(Math.abs(dx)>9&&Math.abs(dx)>Math.abs(dy)*1.08){g.horizontal=true;const targetView=g.direction==='left'?'settings':(view==='settings'?'ride':editorReturnView==='settings'?'settings':'ride');showScreenSwipeBackdrop(targetView,g.direction);g.previewShown=true;screenShell.classList.add('screen-swiping')}else return}const correct=g.direction==='left'?dx<0:dx>0;if(!correct){if(Math.abs(dx)>20){g.cancelled=true;settleScreenSwipe(g,false)}return}const now=performance.now(),dt=Math.max(1,now-g.lastMoveTime);g.velocityX=(e.clientX-g.lastX)/dt;g.lastX=e.clientX;g.lastMoveTime=now;const width=Math.max(document.documentElement.clientWidth||0,window.innerWidth||0),limited=g.direction==='left'?Math.max(-width,Math.min(0,dx)):Math.min(width,Math.max(0,dx));screenShell.style.transition='none';screenShell.style.transform=`translate3d(${limited}px,0,0)`;if(e.cancelable)e.preventDefault()}
function screenSwipeEnd(e){const g=screenSwipe;if(!g||g.pointerId!==e.pointerId)return;screenSwipe=null;if(g.cancelled||!g.horizontal){if(g.previewShown)settleScreenSwipe(g,false);return}const width=Math.max(document.documentElement.clientWidth||0,window.innerWidth||0),distance=Math.min(150,Math.max(SCREEN_EDGE_SWIPE_DISTANCE,width*.24)),speed=g.direction==='left'?-g.velocityX:g.velocityX,correctDistance=g.direction==='left'?-g.dx:g.dx,complete=correctDistance>=distance||(correctDistance>=30&&speed>=SCREEN_SWIPE_VELOCITY);settleScreenSwipe(g,complete)}
function screenSwipeCancel(){const g=screenSwipe;screenSwipe=null;if(g?.horizontal)settleScreenSwipe(g,false);else resetScreenSwipeVisuals()}
"""
if old_swipe not in s: raise SystemExit('screen swipe block not found')
s=s.replace(old_swipe,new_swipe,1)

if "0.28.20" not in s: raise SystemExit('new version missing')
for marker in ['class="quickbar"','function renderQuickBar','function screenSwipePreviewHtml','SCREEN_EDGE_SWIPE_ZONE=64','data-action="quick-primary"']:
    if marker not in s: raise SystemExit('missing marker '+marker)
p.write_text(s)

sw=Path('service-worker.js')
w=sw.read_text()
if "kmreg-shell-0.28.19" not in w: raise SystemExit('service worker version marker missing')
